//
// The ramp and its contrast floors are defined and verified in that script,
// which CI runs. Editing a value here would pass the build and silently break
// the guarantee that every numeral clears 4.5:1 on its own card.

import SwiftUI

/// Colours for the thirteen card values.
///
/// Hue belongs to values. States are expressed with luminance, saturation and
/// motion, never a new hue on a card, because thirteen values already consume
/// nearly the whole wheel.
enum CardPalette {
  /// The card surface. Low chroma; this is the resting state.
  static func wash(for value: Int) -> Color { dynamic(washes, value) }

  /// The numeral. Solved to at least 4.5:1 against its own wash in both modes.
  static func ink(for value: Int) -> Color { dynamic(inks, value) }

  /// Full chroma. The Rail, and the card edge at 35%.
  static func rail(for value: Int) -> Color { dynamic(rails, value) }

  private static func dynamic(_ ramp: [(light: UInt32, dark: UInt32)], _ value: Int) -> Color {
    let pair = ramp[min(max(value, 0), ramp.count - 1)]
    return Color(
      UIColor { traits in
        UIColor(rgb: traits.userInterfaceStyle == .dark ? pair.dark : pair.light)
      })
  }

  private static let washes: [(light: UInt32, dark: UInt32)] = [
    (light: 0xDBDBDB, dark: 0x424242),
