extension UIColor {
  fileprivate convenience init(rgb: UInt32) {
    self.init(
      red: CGFloat((rgb >> 16) & 0xFF) / 255,
      green: CGFloat((rgb >> 8) & 0xFF) / 255,
      blue: CGFloat(rgb & 0xFF) / 255,
      alpha: 1
    )
  }
}

/// Table and surface tokens.
///
/// The table is true black in dark mode, not a lifted grey: tinted cards pop
/// hardest on black, and on OLED it is a real energy saving.
enum TablePalette {
  static let table = Color(
    UIColor { $0.userInterfaceStyle == .dark ? .black : .systemGroupedBackground })
  static let surface = Color(.secondarySystemGroupedBackground)
}
